/* ==========================================================================
   Recorded sounds: real blades, footsteps, metal, cloth and body falls (CC0,
   from Kenney's RPG Audio pack) played over or in place of the synthesized ones.
   Until the clips have decoded, the synthesized sound plays instead.
   ========================================================================== */

(function recordedSounds() {
  const DATA = {"chop": "", "cloth1": "", "cloth2": "", "cloth3": "", "doorClose_1": "", "doorClose_3": "", "doorOpen_1": "", "dropLeather": "", "footstep00": "", "footstep02": "", "footstep04": "", "footstep06": "", "footstep08": "", "knifeSlice": "", "knifeSlice2": "", "metalClick": "", "metalPot1": "", "metalPot2": ""};
  // event -> [clip names, volume, replaces the synthesized sound?, pitch spread]
  const USE = {"step": [["footstep00", "footstep02", "footstep04", "footstep06", "footstep08"], 0.45, true, 0.12], "land": [["footstep04", "dropLeather"], 0.8, false, 0.08], "punch": [["chop"], 0.7, false, 0.12], "kick": [["chop", "dropLeather"], 0.9, false, 0.1], "smash": [["dropLeather", "doorClose_3"], 1.0, false, 0.08], "ko": [["dropLeather"], 1.0, false, 0.08], "down": [["dropLeather"], 0.9, false, 0.08], "thud": [["doorClose_1"], 1.0, false, 0.06], "swish": [["cloth2", "cloth3"], 0.6, false, 0.12], "sweep": [["cloth1"], 0.8, false, 0.1], "dash": [["cloth1", "cloth2"], 0.9, false, 0.1], "whip": [["cloth3"], 0.8, false, 0.15], "slash": [["knifeSlice", "knifeSlice2"], 0.9, false, 0.08], "star": [["knifeSlice"], 0.5, false, 0.2], "parry": [["metalPot1", "metalPot2"], 0.7, false, 0.08], "clang": [["metalPot2", "metalClick"], 0.7, false, 0.08], "break": [["doorClose_3"], 0.9, false, 0.1], "door": [["doorOpen_1"], 1.0, false, 0.03], "grab": [["cloth1"], 0.7, false, 0.1]};
  const clips = {};
  let loading = false;
  function load(chip) {
    if (loading) return;
    loading = true;
    for (const k in DATA) {
      try {
        const bin = atob(DATA[k]), buf = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
        const done = (b) => { clips[k] = b; };
        const p = chip.ctx.decodeAudioData(buf.buffer, done, () => {});
        if (p && p.catch) p.catch(() => {});
      } catch (e) { /* this clip stays synthesized */ }
    }
  }
  const base = Chip.prototype.sfx;
  Chip.prototype.sfx = function (name, opt) {
    const u = USE[name];
    if (u && this.ok() && !this.mute) {
      load(this);
      const b = clips[u[0][Math.floor(Math.random() * u[0].length)]];
      if (b) {
        const c = this.ctx, s = c.createBufferSource(), g = c.createGain();
        s.buffer = b; s.playbackRate.value = 1 + (Math.random() * 2 - 1) * (u[3] || 0.06);
        g.gain.value = u[1] * 0.55;
        s.connect(g); g.connect(this.sfxBus); s.start();
        if (u[2]) return 0;
      }
    }
    return base.call(this, name, opt);
  };
})();
